  2920      (void) type, (void) moveToken;
  2921      /*EXTENSIONOBJECT POSITION!*/
  2922      UA_UInt16 old_index = parseCtx->index;
  2923      UA_Boolean typeIdFound;
  2924
  2925      /* Decode the DataType */
  2926      UA_NodeId typeId;
  2927      UA_NodeId_init(&typeId);
  2928
  2929      size_t searchTypeIdResult = 0;
  2930      status ret = lookAheadForKey(UA_JSONKEY_TYPEID, ctx, parseCtx, &searchTypeIdResult);
  2931
  2932      if(ret != UA_STATUSCODE_GOOD) {
  2933          /*No Typeid found*/
  2934          typeIdFound = false;
  2935          /*return UA_STATUSCODE_BADDECODINGERROR;*/
  2936      } else {
  2937          typeIdFound = true;
  2938          /* parse the nodeid */
  2939          parseCtx->index = (UA_UInt16)searchTypeIdResult;
  2940          ret = NodeId_decodeJson(&typeId, &UA_TYPES[UA_TYPES_NODEID], ctx, parseCtx, true);
  2941          if(ret != UA_STATUSCODE_GOOD) {
  2942              UA_NodeId_deleteMembers(&typeId);
  2943              return ret;
  2944          }
  2945
  2946          /*restore index, ExtensionObject position*/
  2947          parseCtx->index = old_index;
  2948      }
  2949
  2950      /* ---Decode the EncodingByte--- */
  2951      if(!typeIdFound)
  2952          return UA_STATUSCODE_BADDECODINGERROR;
  2953
  2954      UA_Boolean encodingFound = false;
  2955      /*Search for Encoding*/
  2956      size_t searchEncodingResult = 0;
  2957      ret = lookAheadForKey(UA_JSONKEY_ENCODING, ctx, parseCtx, &searchEncodingResult);
  2958
  2959      UA_UInt64 encoding = 0;
  2960      /*If no encoding found it is Structure encoding*/
  2961      if(ret == UA_STATUSCODE_GOOD) { /*FOUND*/
  2962          encodingFound = true;
  2963          char *extObjEncoding = (char*)(ctx->pos + parseCtx->tokenArray[searchEncodingResult].start);
  2964          size_t size = (size_t)(parseCtx->tokenArray[searchEncodingResult].end
  2965                                 - parseCtx->tokenArray[searchEncodingResult].start);
  2966          atoiUnsigned(extObjEncoding, size, &encoding);
  2967      }
  2968
  2969      const UA_DataType *typeOfBody = UA_findDataType(&typeId);
  2970
  2971      if(encoding == 0 || typeOfBody != NULL) {
  2972          /*This value is 0 if the body is Structure encoded as a JSON object (see 5.4.6).*/
  2973          /* Found a valid type and it is structure encoded so it can be unwrapped */
  2974          dst->type = typeOfBody;
  2975
  2976          /* Allocate memory for type*/
  2977          dst->data = UA_new(dst->type);
  2978          if(!dst->data) {
  2979              UA_NodeId_deleteMembers(&typeId);
  2980              return UA_STATUSCODE_BADOUTOFMEMORY;
  2981          }
  2982
  2983          /* Decode the content */
  2984          UA_NodeId nodeIddummy;
  2985          DecodeEntry entries[3] =
  2986              {
  2987               {UA_JSONKEY_TYPEID, &nodeIddummy, (decodeJsonSignature) NodeId_decodeJson, false, NULL},
  2988               {UA_JSONKEY_BODY, dst->data,
  2989                (decodeJsonSignature) decodeJsonJumpTable[dst->type->typeKind], false, NULL},
  2990               {UA_JSONKEY_ENCODING, NULL, NULL, false, NULL}};
  2991
  2992          ret = decodeFields(ctx, parseCtx, entries, encodingFound ? 3:2, typeOfBody);
  2993          if(ret != UA_STATUSCODE_GOOD) {
  2994              UA_free(dst->data);
  2995          }
  2996      } else if(encoding == 1 || encoding == 2 || typeOfBody == NULL) {
  2997          UA_NodeId_deleteMembers(&typeId);
  2998
  2999          /* decode as ExtensionObject */
  3000          dst->type = &UA_TYPES[UA_TYPES_EXTENSIONOBJECT];
  3050  }
