  3053  decodeFields(CtxJson *ctx, ParseCtx *parseCtx, DecodeEntry *entries,
  3054               size_t entryCount, const UA_DataType *type) {
  3055      CHECK_TOKEN_BOUNDS;
  3056      size_t objectCount = (size_t)(parseCtx->tokenArray[parseCtx->index].size);
  3057      status ret = UA_STATUSCODE_GOOD;
  3058
  3059      if(entryCount == 1) {
  3060          if(*(entries[0].fieldName) == 0) { /*No MemberName*/
  3061              return entries[0].function(entries[0].fieldPointer, type,
  3062                                         ctx, parseCtx, true); /*ENCODE DIRECT*/
  3063          }
  3064      } else if(entryCount == 0) {
  3065          return UA_STATUSCODE_BADDECODINGERROR;
  3066      }
  3067
  3068      parseCtx->index++; /*go to first key*/
  3069      CHECK_TOKEN_BOUNDS;
  3070
  3071      for (size_t currentObjectCount = 0; currentObjectCount < objectCount &&
  3072               parseCtx->index < parseCtx->tokenCount; currentObjectCount++) {
  3073
  3074          /* start searching at the index of currentObjectCount */
  3075          for (size_t i = currentObjectCount; i < entryCount + currentObjectCount; i++) {
  3076              /* Search for KEY, if found outer loop will be one less. Best case
  3077               * is objectCount if in order! */
  3078              size_t index = i % entryCount;
  3079
  3080              CHECK_TOKEN_BOUNDS;
  3081              if(jsoneq((char*) ctx->pos, &parseCtx->tokenArray[parseCtx->index],
  3082                         entries[index].fieldName) != 0)
  3083                  continue;
  3084
  3085              if(entries[index].found) {
  3086                  /*Duplicate Key found, abort.*/
  3087                  return UA_STATUSCODE_BADDECODINGERROR;
  3088              }
  3089
  3090              entries[index].found = true;
  3091
  3092              parseCtx->index++; /*goto value*/
  3093              CHECK_TOKEN_BOUNDS;
